import os
from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential

def extract_document_layout(document_path: str) -> dict:
    endpoint = os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
    api_key = os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_KEY")

    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(api_key))

    with open(document_path, "rb") as f:
        poller = client.begin_analyze_document(model_id="prebuilt-layout", document=f)
        result = poller.result()

    layout_data = {"pages": [], "tables": []}

    if result.pages:
        for page in result.pages:
            page_info = {
                "page_number": page.page_number,
                "width": page.width,
                "height": page.height,
                "unit": page.unit,
                "lines": [],
                "words": []
            }
            for line in page.lines:
                page_info["lines"].append({
                    "content": line.content,
                    "polygon": line.polygon
                })
            for word in page.words:
                page_info["words"].append({
                    "content": word.content,
                    "confidence": word.confidence,
                    "polygon": word.polygon
                })
            layout_data["pages"].append(page_info)

    if result.tables:
        for table in result.tables:
            table_info = {
                "row_count": table.row_count,
                "column_count": table.column_count,
                "cells": []
            }
            for cell in table.cells:
                table_info["cells"].append({
                    "row_index": cell.row_index,
                    "column_index": cell.column_index,
                    "content": cell.content,
                    "is_header": cell.is_header
                })
            layout_data["tables"].append(table_info)

    return layout_data
